insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ContractCheck', 'contract-check', 'Know what you are signing before you sign it', 'ContractCheck reviews contracts and highlights key clauses, unusual terms, and potential risks in plain English. It flags auto-renewal traps, liability limits, IP ownership issues, and termination conditions - so you walk into every negotiation informed, even without a lawyer on call.', 'https://example.com/contractcheck', 'https://api.dicebear.com/7.x/shapes/svg?seed=contractcheck&backgroundColor=c7d2fe', 'Legal', ARRAY['Legal', 'Finance', 'Operations', 'Executive', 'Real Estate'], ARRAY['DocuSign', 'Google Drive', 'Dropbox', 'Microsoft Word', 'Notion'], 'freemium', 'plug_and_play', true, 4.6, 334);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ContentCalAI', 'content-cal-ai', 'A month of social content, planned and drafted in an afternoon', 'ContentCalAI generates a full monthly content calendar tailored to your brand, industry, and goals. It drafts captions, suggests visuals, and schedules posts across your channels. Marketing teams use it to stay consistent without scrambling for ideas every week.', 'https://example.com/contentcalai', 'https://api.dicebear.com/7.x/shapes/svg?seed=contentcalai&backgroundColor=d9f99d', 'Marketing', ARRAY['Marketing', 'E-commerce', 'SaaS', 'Retail', 'Media'], ARRAY['LinkedIn', 'Instagram', 'Twitter', 'Buffer', 'Hootsuite', 'Notion'], 'subscription', 'plug_and_play', true, 4.4, 412);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('AdOptimizer', 'ad-optimizer', 'Stop wasting ad budget on what is not working', 'AdOptimizer monitors your paid campaigns across Google and Meta, identifies underperforming ads, and suggests copy and targeting tweaks backed by your own performance data. Marketing managers get a weekly action plan - no agency or data analyst required.', 'https://example.com/adoptimizer', 'https://api.dicebear.com/7.x/shapes/svg?seed=adoptimizer&backgroundColor=fcd34d', 'Marketing', ARRAY['E-commerce', 'SaaS', 'Retail', 'Marketing'], ARRAY['Google Ads', 'Meta Ads', 'Shopify', 'HubSpot', 'Google Analytics'], 'subscription', 'low', true, 4.3, 176);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('AccessAudit', 'access-audit', 'Know exactly who has access to what - and flag what should not be there', 'AccessAudit scans your SaaS tools and surfaces employees with excessive permissions, dormant accounts that should be deactivated, and apps your team is using that IT does not know about. It produces a clean access report that takes minutes to review, not days to compile.', 'https://example.com/accessaudit', 'https://api.dicebear.com/7.x/shapes/svg?seed=accessaudit&backgroundColor=e2e8f0', 'IT & Security', ARRAY['IT', 'Security', 'Finance', 'Healthcare', 'Legal'], ARRAY['Okta', 'Google Workspace', 'Microsoft 365', 'Slack', 'GitHub', 'Salesforce'], 'subscription', 'medium', true, 4.5, 118);
